            case "sienna": return new int[]{160, 82, 45};
            case "silver": return new int[]{192, 192, 192};
            case "skyblue": return new int[]{135, 206, 235};
            case "slateblue": return new int[]{106, 90, 205};
            case "slategray": return new int[]{112, 128, 144};
            case "snow": return new int[]{255, 250, 250};
            case "springgreen": return new int[]{0, 255, 127};
            case "steelblue": return new int[]{70, 130, 180};
            case "tan": return new int[]{210, 180, 140};
            case "teal": return new int[]{0, 128, 128};
            case "thistle": return new int[]{216, 191, 216};
            case "tomato": return new int[]{255, 99, 71};
            case "turquoise": return new int[]{64, 224, 208};
            case "violet": return new int[]{238, 130, 238};
            case "violetred": return new int[]{208, 32, 144};
            case "wheat": return new int[]{245, 222, 179};
            case "white": return new int[]{255, 255, 255};
            case "whitesmoke": return new int[]{245, 245, 245};
            case "yellow": return new int[]{255, 255, 0};
            case "yellowgreen": return new int[]{154, 205, 50};
        }

        // 如果是 #xxx 格式的颜色值，转换为 #xxxxxx 格式
        if (hex.charAt(0) == '#' && hex.length() == 4) {
            hex = String.format(
                    "#%c%c%c%c%c%c",
                    hex.charAt(1), hex.charAt(1),
                    hex.charAt(2), hex.charAt(2),
                    hex.charAt(3), hex.charAt(3));
        }
        // 若是 rgb(x,x,x) 格式的颜色值，返回对应的 int 数组
        if (hex.startsWith("rgb(") && hex.endsWith(")")) {
            String[] rgb = hex.substring(4, hex.length() - 1).split(",");
            return new int[]{
                    Integer.decode(rgb[0].trim()),
                    Integer.decode(rgb[1].trim()),
                    Integer.decode(rgb[2].trim())
            };
        }
        // 若是 rgba(x,x,x,x) 格式的颜色值，返回对应的 int 数组
        if (hex.startsWith("rgba(") && hex.endsWith(")")) {
            String[] rgba = hex.substring(5, hex.length() - 1).split(",");
            return new int[]{
                    Integer.decode(rgba[0].trim()),
                    Integer.decode(rgba[1].trim()),
                    Integer.decode(rgba[2].trim()),
                    (int) (255 * Double.parseDouble(rgba[3]))
            };
        }

        // 尝试解析 #xxxxxx 格式的颜色值
        try {
            Color c = Color.decode(hex);
            return new int[]{c.getRed(), c.getGreen(), c.getBlue()};
        } catch (Exception e) {
            // 无法解析时返回黑色
            return null;
        }
    }

