package org.ofdrw.layout.element.canvas;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class NamedColorRgbTests {

    @Test
    void nullAndInitiallyEmptyInputsReturnNull() {
        assertNull(NamedColor.rgb(null));
        assertNull(NamedColor.rgb(""));
    }

    @Test
    void namedColorsAreTrimmedAndCaseInsensitive() {
        assertArrayEquals(new int[]{255, 0, 0}, NamedColor.rgb("  ReD  "));
        assertArrayEquals(new int[]{0, 128, 0}, NamedColor.rgb("GREEN"));
    }

    @Test
    void namedColorResultsAreFreshArrays() {
        int[] first = NamedColor.rgb("blue");
        int[] second = NamedColor.rgb("blue");

        assertArrayEquals(new int[]{0, 0, 255}, first);
        assertArrayEquals(new int[]{0, 0, 255}, second);
        assertNotSame(first, second);
    }

    @Test
    void threeDigitHexadecimalColorsAreExpanded() {
        assertArrayEquals(new int[]{170, 187, 204}, NamedColor.rgb(" #abc "));
        assertArrayEquals(new int[]{255, 0, 255}, NamedColor.rgb("#F0F"));
    }

    @Test
    void rgbFormParsesTrimmedIntegerComponents() {
        assertArrayEquals(
                new int[]{12, 34, 56},
                NamedColor.rgb(" RGB( 12, 34, 56 ) ")
        );
    }

    @Test
    void rgbaFormReturnsRgbComponentsAndComputedAlpha() {
        assertArrayEquals(
                new int[]{10, 20, 30, 127},
                NamedColor.rgb("rgba(10, 20, 30, 0.5)")
        );
    }

    @Test
    void hexadecimalValuesAreDecodedToRgb() {
        assertArrayEquals(
                new int[]{18, 171, 239},
                NamedColor.rgb("#12abef")
        );
    }

    @Test
    void undecodableNonColorReturnsNull() {
        assertNull(NamedColor.rgb("not-a-color"));
    }

    @Test
    void whitespaceOnlyInputCanPropagateAnUncheckedException() {
        assertThrows(RuntimeException.class, () -> NamedColor.rgb("   "));
    }
}

package org.ofdrw.layout.element.canvas;

import org.junit.jupiter.api.Test;

import java.awt.Color;

import static org.junit.jupiter.api.Assertions.*;

public class NamedColorRgbTests {

    @Test
    void testNullInputReturnsNull() {
        assertNull(NamedColor.rgb(null));
    }

    @Test
    void testEmptyInputReturnsNull() {
        assertNull(NamedColor.rgb(""));
    }

    @Test
    void testWhitespaceOnlyThrows() {
        assertThrows(StringIndexOutOfBoundsException.class, () -> NamedColor.rgb("   "));
    }

    @Test
    void testThreeDigitHexExpansionViaHash() {
        int[] actual = NamedColor.rgb("#abc");
        int r = Integer.parseInt("aa", 16);
        int g = Integer.parseInt("bb", 16);
        int b = Integer.parseInt("cc", 16);
        int[] expected = new int[]{r, g, b};
        assertArrayEquals(expected, actual);
    }

    @Test
    void testRgbFunctionParsing() {
        int[] actual = NamedColor.rgb("rgb(12, 34, 56)");
        assertArrayEquals(new int[]{12, 34, 56}, actual);
    }

    @Test
    void testRgbaFunctionParsing() {
        int[] actual = NamedColor.rgb("rgba(10,20,30,0.5)");
        int alpha = (int) (255 * 0.5);
        assertArrayEquals(new int[]{10, 20, 30, alpha}, actual);
    }

    @Test
    void testHexDecodingFallback() {
        Color c = Color.decode("#112233");
        int[] expected = new int[]{c.getRed(), c.getGreen(), c.getBlue()};
        int[] actual = NamedColor.rgb("#112233");
        assertArrayEquals(expected, actual);
    }

    @Test
    void testHexWith0xPrefixDecodedViaColorDecode() {
        Color c = Color.decode("0xaabbcc");
        int[] expected = new int[]{c.getRed(), c.getGreen(), c.getBlue()};
        int[] actual = NamedColor.rgb("0xaabbcc");
        assertArrayEquals(expected, actual);
    }

    @Test
    void testUnknownValueReturnsNull() {
        assertNull(NamedColor.rgb("notacolor"));
    }

    @Test
    void testNamedColorProducesThreeElements() {
        int[] actual = NamedColor.rgb("aqua");
        assertNotNull(actual);
        assertEquals(3, actual.length);
    }
}

