package org.ofdrw.layout.engine.render;

import org.junit.jupiter.api.Test;
import org.ofdrw.core.basicStructure.pageObj.layer.block.CT_PageBlock;
import org.ofdrw.core.basicStructure.pageObj.layer.block.PathObject;
import org.ofdrw.layout.element.Div;

import java.lang.reflect.Method;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

class DivRenderRenderTests {

    @Test
    void returnsWithoutRenderingWhenDivHasNoBackgroundOrBorder() {
        Div<?> div = new Div<>();
        AtomicInteger maxUnitId = new AtomicInteger(17);
        CT_PageBlock layer = new CT_PageBlock();

        DivRender.render(layer, div, maxUnitId);

        assertEquals(17, maxUnitId.get());
        assertEquals(0, layer.getPageBlocks().size());
    }

    @Test
    void requiresHeightWhenRenderingIsNeeded() {
        Div<?> div = new Div<>();
        div.setBackgroundColor(12, 34, 56);
        AtomicInteger maxUnitId = new AtomicInteger(4);
        CT_PageBlock layer = new CT_PageBlock();

        assertThrows(
                IllegalArgumentException.class,
                () -> DivRender.render(layer, div, maxUnitId)
        );

        assertEquals(4, maxUnitId.get());
        assertEquals(0, layer.getPageBlocks().size());
    }

    @Test
    void preservesConfiguredDashPatternEvenWhenOpacityIsSet() throws Exception {
        Div<?> div = new Div<>(10d, 20d, 80d, 40d);
        div.setBorder(2d)
                .setOpacity(0.5d)
                .setBorderDash(3d);

        AtomicInteger maxUnitId = new AtomicInteger(9);
        CT_PageBlock layer = new CT_PageBlock();

        DivRender.render(layer, div, maxUnitId);

        assertEquals(1, layer.getPageBlocks().size());
        assertEquals(10, maxUnitId.get());

        PathObject border = (PathObject) layer.getPageBlocks().get(0);
        Object dash = null;
        for (Method method : border.getClass().getMethods()) {
            if (method.getParameterCount() == 0
                    && method.getName().toLowerCase().contains("dash")
                    && method.getReturnType() != Void.TYPE) {
                dash = method.invoke(border);
                break;
            }
        }
        assertNotNull(dash);
    }
}

package org.ofdrw.layout.engine.render;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.ofdrw.core.basicStructure.pageObj.layer.block.CT_PageBlock;
import org.ofdrw.core.basicStructure.pageObj.layer.block.PathObject;
import org.ofdrw.layout.element.Div;

/**
 * Unit tests for DivRender.render behavior.
 * Focuses on observable behaviors described in the specification,
 * and tries to distinguish correct implementation from potential defects.
 */
public class DivRenderRenderTests {

    @Test
    public void testRender_NoBackgroundNoBorder_NoBlocksAndIDUnchanged() {
        // Arrange
        CT_PageBlock layer = new CT_PageBlock();
        Div<?> e = new Div(0d, 0d, 100d, 50d); // default: no bg, no border
        AtomicInteger maxUnitID = new AtomicInteger(0);

        // Act
        DivRender.render(layer, e, maxUnitID);

        // Assert
        List<?> blocks = layer.getPageBlocks();
        assertNotNull(blocks, "Layer should expose a non-null list of page blocks");
        assertEquals(0, blocks.size(), "No background or border should be drawn, hence no blocks");
        assertEquals(0, maxUnitID.get(), "maxUnitID should not be incremented when nothing is drawn");
    }

    @Test
    public void testRender_BackgroundWithUniformBorderCreatesTwoBlocks() {
        // Arrange
        CT_PageBlock layer = new CT_PageBlock();
        Div<?> e = new Div(0d, 0d, 100d, 50d)
                .setBackgroundColor(255, 0, 0)
                .setBorderTop(2d).setBorderRight(2d).setBorderBottom(2d).setBorderLeft(2d);
        AtomicInteger maxUnitID = new AtomicInteger(0);

        // Act
        DivRender.render(layer, e, maxUnitID);

        // Assert
        List<?> blocks = layer.getPageBlocks();
        assertEquals(2, blocks.size(), "Background and uniform border should produce two path blocks");

        // The first should be a background PathObject, the second the border PathObject
        assertTrue(blocks.get(0) instanceof PathObject, "First block should be a PathObject (background)");
        assertTrue(blocks.get(1) instanceof PathObject, "Second block should be a PathObject (border)");
    }

    @Test
    public void testRender_UnequalBordersTopBottomOnlyCreatesTwoBlocks() {
        // Arrange
        CT_PageBlock layer = new CT_PageBlock();
        Div<?> e = new Div(0d, 0d, 100d, 50d)
                .setBorderTop(3d).setBorderBottom(3d); // unequal borders because left/right are zero
        AtomicInteger maxUnitID = new AtomicInteger(0);

        // Act
        DivRender.render(layer, e, maxUnitID);

        // Assert
        List<?> blocks = layer.getPageBlocks();
        // Expect top and bottom borders only, since left/right widths are 0
        assertEquals(2, blocks.size(), "Top and bottom borders should be drawn when widths are non-zero; left/right should be skipped");
        assertTrue(blocks.get(0) instanceof PathObject, "Top border should be represented as a PathObject");
        assertTrue(blocks.get(1) instanceof PathObject, "Bottom border should be represented as a PathObject");
    }

    @Test
    public void testRender_HeightNullThrowsIllegalArgument() {
        // Arrange
        CT_PageBlock layer = new CT_PageBlock();
        Div<?> e = new Div(0d, 0d, 100d, 50d)
                .setBackgroundColor(0, 0, 0); // ensure a background exists to trigger height check path
        // Force height to null to trigger exception according to spec
        e.setHeight(null);
        AtomicInteger maxUnitID = new AtomicInteger(0);

        // Act & Assert
        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> DivRender.render(layer, e, maxUnitID),
                "Expected IllegalArgumentException when height is null and rendering is required");
        assertTrue(ex.getMessage().contains("高度"), "Error message should indicate height requirement");
    }
}
